static int skip_chunk(struct http_message *hm) {
    char *s = hm->body.start;
    char *end = hm->body.start + hm->body.len;
    unsigned long n = 0;
    int i = 0;

    while (s < end) {
        if (*s == '\r' && s+1 < end && *(s+1) == '\n') {
            s += 2;
            break;
        }
        if (i >= (int) sizeof(n) * 2) {
            return -1;  // Chunk size too long
        }
        n *= 16;
        if (*s >= '0' && *s <= '9') {
            n += *s - '0';
        } else if (*s >= 'A' && *s <= 'F') {
            n += *s - 'A' + 10;
        } else if (*s >= 'a' && *s <= 'f') {
            n += *s - 'a' + 10;
        } else {
            return -1;  // Invalid hex digit
        }
        s++;
        i++;
    }
    hm->chunk_size = n;
    hm->body.start = s;
    hm->body.len = end - s;
    return 0;
}

